#!/usr/bin/env node
import fs from 'node:fs';
import path from 'node:path';
import zlib from 'node:zlib';

const root = process.cwd();
const targetVersion = '0.27.0';
const expectedBase = '0.26.0';
const files = {
  "ASSET_MANAGEMENT_0.27.md": "",
  "README.md": "",
  "README_NASADENIE_0.27.txt": "",
  "RELEASE_NOTES_0.27.md": "",
  "package.json": "",
  "src/App.tsx": "",
  "src/data/seed.json": "",
  "src/lib/assetImport.ts": "",
  "src/lib/storage.ts": "",
  "src/types.ts": "",
  "src/views/Cmdb.css": "",
  "src/views/Cmdb.tsx": "",
  "src/views/DepartmentPortal.tsx": ""
};

function readJson(file) {
  try { return JSON.parse(fs.readFileSync(file, 'utf8')); } catch { return null; }
}
function stamp() { return new Date().toISOString().replace(/[:.]/g, '-'); }

const pkgPath = path.join(root, 'package.json');
if (!fs.existsSync(pkgPath)) {
  console.error('ERROR: Spustite installer v koreni projektu (package.json nebol najdeny).');
  process.exit(1);
}
const pkg = readJson(pkgPath);
const current = String(pkg?.version || '');
if (current !== expectedBase && current !== targetVersion) {
  console.error(`ERROR: Ocakavana verzia ${expectedBase} (alebo uz ${targetVersion}), najdena ${current || 'nezistena'}.`);
  process.exit(1);
}
if (current === targetVersion) console.log('INFO: Projekt uz hlasi v0.27.0; subory sa overia/prepisu idempotentne.');

const backupRoot = path.join(root, `backup-before-v0270-${stamp()}`);
fs.mkdirSync(backupRoot, { recursive: true });
let written = 0;
for (const [rel, packed] of Object.entries(files)) {
  const destination = path.join(root, rel);
  if (fs.existsSync(destination)) {
    const backup = path.join(backupRoot, rel);
    fs.mkdirSync(path.dirname(backup), { recursive: true });
    fs.copyFileSync(destination, backup);
  }
  fs.mkdirSync(path.dirname(destination), { recursive: true });
  fs.writeFileSync(destination, zlib.gunzipSync(Buffer.from(packed, 'base64')));
  written += 1;
  console.log('WRITE', rel);
}
for (const cache of ['dist', '.vite', 'node_modules/.vite']) {
  const p = path.join(root, cache);
  if (fs.existsSync(p)) fs.rmSync(p, { recursive: true, force: true });
}
const after = readJson(pkgPath);
if (String(after?.version) !== targetVersion) {
  console.error('ERROR: Verifikacia package.json zlyhala.');
  process.exit(2);
}
const cmdb = fs.readFileSync(path.join(root, 'src/views/Cmdb.tsx'), 'utf8');
const importer = fs.readFileSync(path.join(root, 'src/lib/assetImport.ts'), 'utf8');
if (!cmdb.includes('Hromadný import aktív') || !cmdb.includes('Tlačiareň') || !cmdb.includes('MFP') || !importer.includes('readAssetImportFile')) {
  console.error('ERROR: Verifikacia Asset Management modulu zlyhala.');
  process.exit(3);
}
console.log(`VERIFIED: v0.27.0 Asset Management nainstalovany. ${written} suborov. Zaloha: ${path.basename(backupRoot)}`);
console.log('NEXT: npm install && npm run build');
